def download(fname, fp):
    url = [s for s in urls if fname in s][0]
    url = url.replace("/thumb", "")
    url = sub(r"/[^/]+\.png$", "", url)
    print(url)
    response = get(url, headers={"User-Agent": "MyAssetDownloader/1.0 (personal project)"})

    if response.status_code != 200:
        print(f"Failed {fname}")
        return
    print(fname)

    
    with open(fp + f"/{fname}", "wb") as file:
        file.write(response.content)

for i in range(0, 12):
    path = f"/home/ignacioc/Projects/Godot/BaldiOnline2/characters/student/textures/{i}"
    # mkdir(path)
    for angle in [0, 30, 60, 90, 120, 150, 180, 210, 240, 270, 300, 330]:
        download(f"Student_{i}_{angle}_Sheet.png", path)
    download(f"Student_{i}_Yay.png", path)
